import {
  CanActivate,
  ExecutionContext,
  HttpException,
  HttpStatus,
  Injectable
} from "@nestjs/common";

import type { AuthPrincipal } from "../auth/jwt-auth.guard";
import { AppConfigService } from "../config/app-config.service";

interface RateBucket {
  count: number;
  resetAt: number;
}

interface RateLimitedRequest {
  authPrincipal?: AuthPrincipal;
  ip?: string;
  headers?: Record<string, unknown>;
  method?: string;
  originalUrl?: string;
  url?: string;
}

@Injectable()
export class RagRateLimitGuard implements CanActivate {
  private readonly buckets = new Map<string, RateBucket>();

  constructor(private readonly config: AppConfigService) {}

  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest<RateLimitedRequest>();
    const nowMs = Date.now();
    this.pruneExpiredBuckets(nowMs);

    const windowMs = this.config.rag.rateLimitWindowMs;
    const limit = this.resolveLimit(request);
    const key = this.bucketKey(request);
    const existing = this.buckets.get(key);

    if (!existing || existing.resetAt <= nowMs) {
      this.buckets.set(key, { count: 1, resetAt: nowMs + windowMs });
      return true;
    }

    if (existing.count >= limit) {
      throw new HttpException(
        {
          error: "rag_rate_limited",
          message: "Too many RAG requests. Retry after the current rate window."
        },
        HttpStatus.TOO_MANY_REQUESTS
      );
    }

    existing.count += 1;
    return true;
  }

  private resolveLimit(request: RateLimitedRequest): number {
    return this.routeKey(request).includes("/rag/ingest")
      ? this.config.rag.ingestRateLimitMaxRequests
      : this.config.rag.rateLimitMaxRequests;
  }

  private bucketKey(request: RateLimitedRequest): string {
    const principal = request.authPrincipal;
    const subject = principal?.subject ?? "anonymous";
    const tenantId = principal?.tenantId ?? "tenant-unknown";
    return [
      tenantId,
      subject,
      this.routeKey(request),
      this.clientKey(request)
    ].join("|");
  }

  private routeKey(request: RateLimitedRequest): string {
    const method = request.method ?? "UNKNOWN";
    const path = request.originalUrl ?? request.url ?? "unknown";
    return `${method.toUpperCase()} ${path.split("?")[0]}`;
  }

  private clientKey(request: RateLimitedRequest): string {
    const forwardedFor = request.headers?.["x-forwarded-for"];
    if (typeof forwardedFor === "string" && forwardedFor.trim()) {
      return forwardedFor.split(",")[0]?.trim() ?? "ip-unknown";
    }
    return request.ip ?? "ip-unknown";
  }

  private pruneExpiredBuckets(nowMs: number): void {
    for (const [key, bucket] of this.buckets.entries()) {
      if (bucket.resetAt <= nowMs) {
        this.buckets.delete(key);
      }
    }
  }
}
